def merge_tool_results(calls, results):
    call_ids = []
    for c in calls:
        cid = c.get("id")
        if cid in call_ids:
            raise ValueError(f"Duplicate call id: {cid}")
        call_ids.append(cid)

    call_ids_set = set(call_ids)
    result_map = {}
    for r in results:
        rid = r.get("id")
        if rid in call_ids_set:
            result_map[rid] = r.get("content", "")

    output = []
    for c in calls:
        cid = c.get("id")
        if cid in result_map:
            output.append({"id": cid, "status": "done", "content": result_map[cid]})
        else:
            output.append({"id": cid, "status": "pending"})
    return output

