def summarize_usage(events):
    request_max_input = {}
    request_max_output = {}

    for event in events:
        rid = event.get("request_id")
        if rid is None:
            continue

        in_tokens = event.get("input", 0)
        out_tokens = event.get("output", 0)

        if not isinstance(in_tokens, (int, float)) or in_tokens < 0:
            raise ValueError(f"negative or invalid input: {in_tokens}")
        if not isinstance(out_tokens, (int, float)) or out_tokens < 0:
            raise ValueError(f"negative or invalid output: {out_tokens}")

        request_max_input[rid] = max(request_max_input.get(rid, 0), in_tokens)
        request_max_output[rid] = max(request_max_output.get(rid, 0), out_tokens)

    return {
        "input": sum(request_max_input.values()),
        "output": sum(request_max_output.values())
    }

