{"content": "from module import summarize_usage

def test_summarize_usage():
    events = [
        {"request_id": "a", "input_tokens": 10, "output_tokens": 5},
        {"request_id": "a", "input_tokens": 15, "output_tokens": 2},
        {"request_id": "b", "input_tokens": 20, "output_tokens": 10},
        {"request_id": "b", "output_tokens": 15},
        {"request_id": "c", "input_tokens": 5},
    ]
    # Request a: max input 15, max output 5
    # Request b: max input 20, max output 15
    # Request c: max input 5, max output 0
    # Total input: 15 + 20 + 5 = 40
    # Total output: 5 + 15 + 0 = 20
    expected = {"input": 40, "output": 20}
    assert summarize_usage(events) == expected

    events_with_neg = [
        {"request_id": "a", "input_tokens": -1, "output_tokens": 5},
    ]
    try:
        summarize_usage(events_with_neg)
        assert False, "Should have raised ValueError for negative input_tokens"
    except ValueError:
        pass

    events_with_neg_out = [
        {"request_id": "a", "input_tokens": 10, "output_tokens": -1},
    ]
    try:
        summarize_usage(events_with_neg_out)
        assert False, "Should have raised ValueError for negative output_tokens"
    except ValueError:
        pass

    events_empty = []
    assert summarize_usage(events_empty) == {"input": 0, "output": 0}

    events_no_tokens = [
        {"request_id": "a"},
        {"request_id": "b", "input_tokens": 5},
    ]
    assert summarize_usage(events_no_tokens) == {"input": 5, "output": 0}

    print("All tests passed!")

if __name__ == "__main__":
    test_summarize_usage()
